=== FILE: tb/repro_data_byte.v ===
`timescale 1ns / 1ps
// Repro for bucket B1 (data_byte_fail.log): the eight data bits must be sent
// least significant first. Samples each data bit at its centre, timed from
// the start-bit falling edge, and compares the LSB-first byte with the sent one.
module tb_uart_repro;
    localparam integer CPB   = 4;
    localparam integer CLK_P = 10;
    localparam integer BIT_T = CPB * CLK_P;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_P/2) clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    reg     done   = 1'b0;
    reg [8*64-1:0] nonce;

    reg        armed  = 1'b0;
    reg [63:0] fall_t = 64'd0;
    always @(negedge tx) if (armed) begin fall_t = $time; armed = 1'b0; end

    task finish_report;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task wait_until(input [63:0] t);
        begin
            if (t > $time) #(t - $time);
        end
    endtask

    task launch(input [7:0] d, output [63:0] t_fall);
        begin
            armed = 1'b1;
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
            wait (!armed);
            t_fall = fall_t;
        end
    endtask

    task wait_idle;
        begin
            @(negedge clk);
            while (busy) @(negedge clk);
            repeat (4) @(negedge clk);
        end
    endtask

    task check_data(input [7:0] d);
        reg [63:0] t0;
        reg [7:0]  got;
        integer    k;
        begin
            launch(d, t0);
            wait_until(t0 + BIT_T/2 + 2);
            if (tx === 1'b0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK start_bit FAIL data=%h tx=%b", d, tx);
            end
            for (k = 0; k < 8; k = k + 1) begin
                wait_until(t0 + (k + 1) * BIT_T + BIT_T/2 + 2);
                got[k] = tx;
            end
            if (got === d) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK data_byte FAIL sent=%h received_lsb_first=%h", d, got);
            end
            wait_idle;
        end
    endtask

    initial begin
        #100000;
        if (!done) begin
            failed = failed + 1;
            $display("CHECK watchdog FAIL: frame did not complete");
            finish_report;
        end
    end

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (3) @(negedge clk);
        check_data(8'h01);
        check_data(8'h80);
        check_data(8'hC4);
        check_data(8'h0F);
        check_data(8'h96);
        finish_report;
    end
endmodule
=== END FILE ===
