    task finish_report;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task wait_until(input [63:0] t);
        begin
            if (t > $time) #(t - $time);
        end
    endtask

    task launch(input [7:0] d, output [63:0] t_fall);
        begin
            armed = 1'b1;
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
            wait (!armed);
            t_fall = fall_t;
        end
    endtask

    task wait_idle;
        begin
            @(negedge clk);
            while (busy) @(negedge clk);
            repeat (4) @(negedge clk);
        end
