        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (3) @(negedge clk);
        check_parity(8'h01);
        check_parity(8'h03);
        check_parity(8'h07);
        check_parity(8'hFE);
        check_parity(8'h00);
        finish_report;
    end
endmodule
