`timescale 1ns / 1ps
// Repro for bucket B3 (frame_period_fail.log): the stop bit must last a full
// bit time. A new frame is requested on the first clock busy is low; its start
// bit must not fall earlier than 11 bit times after the previous start bit.
module tb_uart_repro;
    localparam integer CPB   = 4;
    localparam integer CLK_P = 10;
    localparam integer BIT_T = CPB * CLK_P;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #(CLK_P/2) clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    reg     done   = 1'b0;
    reg [8*64-1:0] nonce;

    reg        armed  = 1'b0;
    reg [63:0] fall_t = 64'd0;
    always @(negedge tx) if (armed) begin fall_t = $time; armed = 1'b0; end

    task finish_report;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    task wait_until(input [63:0] t);
        begin
            if (t > $time) #(t - $time);
        end
    endtask

    task launch(input [7:0] d, output [63:0] t_fall);
        begin
            armed = 1'b1;
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
            wait (!armed);
            t_fall = fall_t;
        end
    endtask

    task wait_idle;
        begin
            @(negedge clk);
            while (busy) @(negedge clk);
            repeat (4) @(negedge clk);
        end
    endtask

    task check_frame(input [7:0] d);
        reg [63:0] t0;
        reg [63:0] t1;
        begin
            launch(d, t0);
            // middle of the stop bit
            wait_until(t0 + 10 * BIT_T + BIT_T/2 + 2);
            if (tx === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK stop_level FAIL tx=%b", tx);
            end
            // request the next frame as soon as the transmitter is free
            armed = 1'b1;
            @(negedge clk);
            while (busy) @(negedge clk);
            data  = ~d;
            start = 1'b1;
            @(negedge clk);
            start = 1'b0;
            wait (!armed);
            t1 = fall_t;
            if ((t1 - t0) >= 11 * BIT_T) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("CHECK stop_length FAIL next start bit %0d ns after previous, minimum %0d ns",
                         t1 - t0, 11 * BIT_T);
            end
            wait_idle;
        end
    endtask

    initial begin
        #100000;
        if (!done) begin
            failed = failed + 1;
            $display("CHECK watchdog FAIL: frame did not complete");
            finish_report;
        end
    end

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (3) @(negedge clk);
        check_frame(8'h55);
        check_frame(8'h00);
        check_frame(8'hFF);
        finish_report;
    end
endmodule
=== END FILE ===
